      const content = config.content || "\u6682\u65E0\u8BE6\u7EC6\u6587\u672C\u5185\u5BB9\uFF0C\u4EC5\u4F9B\u67E5\u9605\u3002";
      headerHtml = `<div class="work-node-card-header" ondblclick="toggleTertiaryCardMinimize('` + cardId + `', event)" title="\u53CC\u51FB\u6807\u9898\u680F\u6700\u5C0F\u5316/\u5C55\u5F00\u5361\u7247"><span class="work-node-badge" style="background:#f1f5f9; color:#475569; border:1.5px solid #cbd5e1;">\u{1F4C4} \u7B80\u5355\u6587\u672C</span><span class="work-node-title">` + title + '</span><span style="font-size:10px; font-weight:800; color:#64748b;" id="status-text-' + cardId + '">\u{1F4C4} \u4EC5\u67E5\u9605</span></div>';
